import { pool, resolveDatabaseConfig } from './index';
import { hashPassword } from '../services/authService';

// Legacy identifiers retained only for fixture/fallback compatibility.
// Production workspace and user UUIDs are generated by PostgreSQL and read from the session.
export const DEFAULT_TENANT_ID = 'a0000000-0000-0000-0000-000000000001';
export const DEFAULT_USER_ID = 'b0000000-0000-0000-0000-000000000001';

export interface SeedResult {
  tenantId: string;
  userId: string;
  stages: { id: string; name: string }[];
}

/**
 * Idempotently initializes a workspace and its first admin.
 * Secrets are provided by the operator and are never hard-coded in source control.
 * Run migrations before running this command.
 */
export async function seedDefaults(): Promise<SeedResult> {
  const workspaceName = process.env.WORKSPACE_NAME?.trim();
  const workspaceSlug = process.env.WORKSPACE_SLUG?.trim().toLowerCase();
  const adminEmail = process.env.BOOTSTRAP_ADMIN_EMAIL?.trim().toLowerCase();
  const adminPassword = process.env.BOOTSTRAP_ADMIN_PASSWORD;
  const adminName = process.env.BOOTSTRAP_ADMIN_NAME?.trim() || adminEmail?.split('@')[0] || '';

  if (!workspaceName || workspaceName.length > 255) {
    throw new Error('Set WORKSPACE_NAME to the intended CRM workspace name before seeding.');
  }
  if (!workspaceSlug || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(workspaceSlug) || workspaceSlug.length > 100) {
    throw new Error('Set WORKSPACE_SLUG to a unique lowercase URL-safe slug before seeding.');
  }
  if (!adminEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(adminEmail)) {
    throw new Error('Set BOOTSTRAP_ADMIN_EMAIL to a valid email before seeding.');
  }
  if (!adminPassword || adminPassword.length < 12) {
    throw new Error('Set BOOTSTRAP_ADMIN_PASSWORD to a unique password of at least 12 characters before seeding.');
  }

  console.log('[Seed] Creating or verifying the CRM workspace and first admin...');

  const isolatedTestDatabase = process.env.NODE_ENV === 'test' && !resolveDatabaseConfig().isBlocked;
  const tenantRes = await pool.query<{ id: string }>(
    `INSERT INTO tenants (id, name, slug, status, timezone, currency, locale)
     VALUES (COALESCE($1::uuid, gen_random_uuid()), $2, $3, 'active', $4, $5, $6)
     ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, updated_at = NOW()
     RETURNING id::text AS id;`,
    [
      isolatedTestDatabase ? DEFAULT_TENANT_ID : null,
      workspaceName,
      workspaceSlug,
      process.env.DEFAULT_TIMEZONE || 'Asia/Kolkata',
      process.env.DEFAULT_CURRENCY || 'INR',
      process.env.DEFAULT_LOCALE || 'en-IN',
    ]
  );
  const tenantId = tenantRes.rows[0].id;

  // A conflict never overwrites an existing password. New accounts get the operator-supplied hash.
  const passwordHash = await hashPassword(adminPassword);
  const userRes = await pool.query<{ id: string }>(
    `INSERT INTO users (id, email_normalized, display_name, password_hash, status)
     VALUES (COALESCE($1::uuid, gen_random_uuid()), $2, $3, $4, 'active')
     ON CONFLICT (email_normalized) DO UPDATE
       SET display_name = EXCLUDED.display_name,
           password_hash = COALESCE(users.password_hash, EXCLUDED.password_hash),
           updated_at = NOW()
     RETURNING id::text AS id;`,
    [isolatedTestDatabase ? DEFAULT_USER_ID : null, adminEmail, adminName, passwordHash]
  );
  const userId = userRes.rows[0].id;

  let roleRes = await pool.query<{ id: string }>(
    `SELECT id::text AS id FROM roles WHERE tenant_id = $1::uuid AND name = 'Admin' LIMIT 1;`,
    [tenantId]
  );
  if (roleRes.rows.length === 0) {
    roleRes = await pool.query<{ id: string }>(
      `INSERT INTO roles (tenant_id, name, description, is_system)
       VALUES ($1::uuid, 'Admin', 'Full administrative workspace privileges', true)
       RETURNING id::text AS id;`,
      [tenantId]
    );
  }
  const roleId = roleRes.rows[0].id;

  await pool.query(
    `INSERT INTO memberships (tenant_id, user_id, role_id, status)
     VALUES ($1::uuid, $2::uuid, $3::uuid, 'active')
     ON CONFLICT (tenant_id, user_id) DO UPDATE SET status = 'active';`,
    [tenantId, userId, roleId]
  );

  const permissions = [
    'leads:read', 'leads:write', 'leads:delete', 'pipeline:manage',
    'reports:view', 'team:manage', 'settings:manage', 'audit:read', 'integrations:manage',
  ];
  for (const permission of permissions) {
    await pool.query(
      `INSERT INTO role_permissions (role_id, permission_key)
       VALUES ($1::uuid, $2) ON CONFLICT (role_id, permission_key) DO NOTHING;`,
      [roleId, permission]
    );
  }

  const stageDefs = [
    { name: 'New', sortOrder: 1, color: '#155eef', isWon: false, isLost: false },
    { name: 'Contacted', sortOrder: 2, color: '#2e90fa', isWon: false, isLost: false },
    { name: 'Qualified', sortOrder: 3, color: '#7a5af8', isWon: false, isLost: false },
    { name: 'Proposal', sortOrder: 4, color: '#f79009', isWon: false, isLost: false },
    { name: 'Won', sortOrder: 5, color: '#12b76a', isWon: true, isLost: false },
    { name: 'Lost', sortOrder: 6, color: '#f04438', isWon: false, isLost: true },
  ];

  const stages: { id: string; name: string }[] = [];
  for (const stage of stageDefs) {
    const existing = await pool.query<{ id: string; name: string }>(
      'SELECT id::text AS id, name FROM pipeline_stages WHERE tenant_id = $1::uuid AND name = $2 LIMIT 1;',
      [tenantId, stage.name]
    );
    if (existing.rows.length > 0) {
      stages.push(existing.rows[0]);
      continue;
    }
    const inserted = await pool.query<{ id: string; name: string }>(
      `INSERT INTO pipeline_stages (tenant_id, name, sort_order, color_token, is_won, is_lost, active)
       VALUES ($1::uuid, $2, $3, $4, $5, $6, true)
       RETURNING id::text AS id, name;`,
      [tenantId, stage.name, stage.sortOrder, stage.color, stage.isWon, stage.isLost]
    );
    stages.push(inserted.rows[0]);
  }

  await pool.query(
    `INSERT INTO tenant_subscriptions (tenant_id, plan_id, plan_name, status, billing_provider)
     VALUES ($1::uuid, 'starter', 'Free Starter', 'active', 'manual')
     ON CONFLICT (tenant_id) DO NOTHING;`,
    [tenantId]
  );

  if (isolatedTestDatabase) {
    await seedIsolatedTestFixtures(tenantId, userId);
  }

  console.log(`[Seed] Workspace ready. Tenant ID: ${tenantId}; stages: ${stages.length}`);
  return { tenantId, userId, stages };
}


/**
 * Deterministic synthetic identities and records are created only when the operator
 * explicitly runs the seed against a dedicated *_test database. Never called in runtime startup.
 */
async function seedIsolatedTestFixtures(primaryTenantId: string, adminUserId: string): Promise<void> {
  const secondTenantId = 'a0000000-0000-0000-0000-000000000002';
  await pool.query(
    `INSERT INTO tenants (id, name, slug, status, timezone, currency, locale)
     VALUES ($1::uuid, 'CRM QA Isolation Workspace', 'crm-qa-isolation-workspace', 'active', 'Asia/Kolkata', 'INR', 'en-IN')
     ON CONFLICT (id) DO UPDATE SET status = 'active', updated_at = NOW();`,
    [secondTenantId]
  );

  const rolePermissions: Record<string, string[]> = {
    Admin: ['leads:read', 'leads:write', 'leads:delete', 'pipeline:manage', 'reports:view', 'team:manage', 'settings:manage', 'audit:read', 'integrations:manage'],
    'Sales Manager': ['leads:read', 'leads:write', 'pipeline:manage', 'reports:view'],
    'Sales Executive': ['leads:read', 'leads:write'],
    'Read-only': ['leads:read', 'reports:view'],
  };

  async function ensureTestRole(tenantId: string, roleName: string): Promise<string> {
    const found = await pool.query<{ id: string }>(
      'SELECT id::text AS id FROM roles WHERE tenant_id = $1::uuid AND name = $2 LIMIT 1;',
      [tenantId, roleName]
    );
    let roleId = found.rows[0]?.id;
    if (!roleId) {
      const inserted = await pool.query<{ id: string }>(
        'INSERT INTO roles (tenant_id, name, description, is_system) VALUES ($1::uuid, $2, $3, true) RETURNING id::text AS id;',
        [tenantId, roleName, `Isolated CI fixture role: ${roleName}`]
      );
      roleId = inserted.rows[0].id;
    }
    for (const permission of rolePermissions[roleName] || []) {
      await pool.query(
        'INSERT INTO role_permissions (role_id, permission_key) VALUES ($1::uuid, $2) ON CONFLICT DO NOTHING;',
        [roleId, permission]
      );
    }
    return roleId;
  }

  const adminRoleId = await ensureTestRole(secondTenantId, 'Admin');
  const managerRoleId = await ensureTestRole(primaryTenantId, 'Sales Manager');
  const executiveRoleId = await ensureTestRole(primaryTenantId, 'Sales Executive');

  const fixturePasswordHash = await hashPassword('CRM_Test_Only#2026');
  const fixtures = [
    { id: 'b0000000-0000-0000-0000-000000000002', email: 'riya@bringmybite.in', name: 'QA Sales Manager', tenantId: primaryTenantId, roleId: managerRoleId, membershipStatus: 'active', userStatus: 'active' },
    { id: 'b0000000-0000-0000-0000-000000000003', email: 'suspended@bringmybite.in', name: 'QA Suspended Member', tenantId: primaryTenantId, roleId: executiveRoleId, membershipStatus: 'suspended', userStatus: 'active' },
    { id: 'b0000000-0000-0000-0000-000000000004', email: 'other@competitor.in', name: 'QA Isolation Admin', tenantId: secondTenantId, roleId: adminRoleId, membershipStatus: 'active', userStatus: 'active' },
  ];

  for (const fixture of fixtures) {
    await pool.query(
      `INSERT INTO users (id, email_normalized, display_name, password_hash, status)
       VALUES ($1::uuid, $2, $3, $4, $5)
       ON CONFLICT (id) DO UPDATE
         SET email_normalized = EXCLUDED.email_normalized,
             display_name = EXCLUDED.display_name,
             password_hash = EXCLUDED.password_hash,
             status = EXCLUDED.status,
             updated_at = NOW();`,
      [fixture.id, fixture.email, fixture.name, fixturePasswordHash, fixture.userStatus]
    );
    await pool.query(
      `INSERT INTO memberships (tenant_id, user_id, role_id, status)
       VALUES ($1::uuid, $2::uuid, $3::uuid, $4)
       ON CONFLICT (tenant_id, user_id) DO UPDATE SET role_id = EXCLUDED.role_id, status = EXCLUDED.status;`,
      [fixture.tenantId, fixture.id, fixture.roleId, fixture.membershipStatus]
    );
  }

  const initialStage = await pool.query<{ id: string }>(
    'SELECT id::text AS id FROM pipeline_stages WHERE tenant_id = $1::uuid ORDER BY sort_order LIMIT 1;',
    [primaryTenantId]
  );

  await pool.query(
    `INSERT INTO leads (
       id, tenant_id, name, phone_raw, phone_normalized, company_name, source,
       stage_id, qualification_status, owner_user_id, deal_value_minor_units, currency,
       next_action, consent_status, notes, created_by
     ) VALUES (
       'c0000000-0000-0000-0000-000000000001'::uuid, $1::uuid, 'CRM QA Opted-In Lead',
       '+919876543210', '+919876543210', 'CRM Test Company', 'Website', $2::uuid,
       'Qualified', $3::uuid, 2500000, 'INR', 'Call', 'Consented',
       'Synthetic CI fixture with explicit consent for provider-mocked messaging.', $3::uuid
     )
     ON CONFLICT (id) DO UPDATE SET
       tenant_id = EXCLUDED.tenant_id,
       stage_id = EXCLUDED.stage_id,
       consent_status = EXCLUDED.consent_status,
       updated_at = NOW();`,
    [primaryTenantId, initialStage.rows[0]?.id || null, adminUserId]
  );

  await pool.query(
    `INSERT INTO tenant_settings (tenant_id, category, config_data, updated_by, updated_at)
     VALUES ($1::uuid, 'whatsapp', $2::jsonb, $3::uuid, NOW())
     ON CONFLICT (tenant_id, category)
     DO UPDATE SET config_data = EXCLUDED.config_data, updated_by = EXCLUDED.updated_by, updated_at = NOW();`,
    [
      primaryTenantId,
      JSON.stringify({
        provider: 'mock',
        status: 'test_mode',
        phoneNumberId: '9876543210123',
        businessAccountId: '1234567890123',
        accessToken: 'test_token_only_for_ci',
        appSecret: 'unit-test-whatsapp-app-secret',
        webhookVerifyToken: 'oneclick_verify',
      }),
      adminUserId,
    ]
  );

  await pool.query(
    `INSERT INTO tasks (tenant_id, title, task_type, owner_user_id, due_at, timezone, priority, status, created_by)
     SELECT $1::uuid, 'QA seeded follow-up', 'Call', $2::uuid, NOW() + INTERVAL '1 day', 'Asia/Kolkata', 'Medium', 'Pending', $2::uuid
      WHERE NOT EXISTS (SELECT 1 FROM tasks WHERE tenant_id = $1::uuid AND title = 'QA seeded follow-up');`,
    [primaryTenantId, adminUserId]
  );
}

if (require.main === module) {
  seedDefaults()
    .then(() => pool.end().then(() => process.exit(0)))
    .catch(async (err) => {
      console.error('[Seed] Error:', err instanceof Error ? err.message : 'Unknown error');
      await pool.end().catch(() => undefined);
      process.exit(1);
    });
}
